s_wait_alu 0xfffe
s_lshl_b32 s74, 1, s76
s_wait_alu 0xfffe
s_mov_b32 s75, 0
s_wait_alu 0xfffe
s_cmp_eq_u32 s72, 7
s_cbranch_scc0 .Lmask_not_single\@
s_not_b32 s74, s74
s_wait_alu 0xfffe
s_not_b32 s75, s75
s_wait_alu 0xfffe
.Lmask_not_single\@:
s_cmp_eq_u32 s72, 6
s_cselect_b32 s74, 0, s74
s_wait_alu 0xfffe
s_cselect_b32 s75, 0, s75
s_wait_alu 0xfffe
